insert into label_formats (name, code, width_mm, height_mm, preview_type, active, template_file)
values
  ('ZebraDesigner 3 columnas', '3_etiquetas_v3', 100, 25, 'format2', true, '3_etiquetas_v3.zpl')
on conflict (code) do update set
  name = excluded.name,
  width_mm = excluded.width_mm,
  height_mm = excluded.height_mm,
  preview_type = excluded.preview_type,
  active = excluded.active,
  template_file = excluded.template_file;

delete from label_formats
where code not in ('3_etiquetas_v3');

insert into app_settings (key, value)
values ('inventory_print_limit', '400')
on conflict (key) do nothing;

